#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Daily Check-in: one-time Operator setup for the Cloudflare deploy pipeline.
# Run from anywhere: ./scripts/operator-setup.sh
# Needs: Node and npm (npm ci already run), and gh logged in to GitHub.

cd "$(dirname "${BASH_SOURCE[0]}")/.."

WRANGLER_CONFIG="wrangler.jsonc"
PLACEHOLDER_DB_ID="00000000-0000-0000-0000-000000000000"

TOTAL_STAGES=6

banner "Daily Check-in: Cloudflare and GitHub setup"

# ── 1. Log wrangler in to your Cloudflare account ─────────────────────────
stage "Log wrangler in to Cloudflare"
say "wrangler needs your Cloudflare login on this machine to create the database."
say "This login stays on your computer; CI uses a separate scoped API token."
if npx wrangler whoami 2>/dev/null | grep -q "You are logged in"; then
  note "wrangler is already logged in."
else
  step "A browser tab opens; log in and allow wrangler access."
  npx wrangler login
fi
pause "Press Enter once 'npx wrangler whoami' shows your account."

# ── 2. Make sure the account has a workers.dev subdomain ──────────────────
stage "Check your workers.dev subdomain"
say "The app is served at daily-checkin.<your-subdomain>.workers.dev."
say "CI cannot pick the subdomain for you, so it must exist before the first deploy."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Open Workers & Pages. If Cloudflare asks you to choose a workers.dev subdomain, choose one."
step "If you have deployed a Worker before, the subdomain already exists; nothing to do."
ask WORKERS_SUBDOMAIN "Type your workers.dev subdomain (the part before .workers.dev):"

# ── 3. Create the D1 database and record its id ───────────────────────────
stage "Create the D1 database"
if ! grep -q "$PLACEHOLDER_DB_ID" "$WRANGLER_CONFIG"; then
  note "$WRANGLER_CONFIG already holds a real database_id; skipping."
else
  say "This creates an empty D1 database named daily-checkin in your account."
  say "If it already exists, wrangler says so; run 'npx wrangler d1 list' to see its id."
  if confirm "Create the daily-checkin D1 database now?"; then
    npx wrangler d1 create daily-checkin || warn "create failed; if it already exists, copy its id from 'npx wrangler d1 list'."
  fi
  step "Copy the database_id that wrangler printed (a UUID)."
  ask D1_DATABASE_ID "Paste the database_id:"
  if [[ ! "$D1_DATABASE_ID" =~ ^[0-9a-fA-F-]{36}$ ]]; then
    printf '  %sThat does not look like a database id. Re-run the wizard.%s\n' "$RED" "$RESET"
    exit 1
  fi
  sed -i.bak "s/$PLACEHOLDER_DB_ID/$D1_DATABASE_ID/" "$WRANGLER_CONFIG" && rm -f "$WRANGLER_CONFIG.bak"
  printf '  %s✓ wrote%s database_id → %s\n' "$GREEN" "$RESET" "$WRANGLER_CONFIG"
  SKIPPED+=("commit the database_id in $WRANGLER_CONFIG to the pull request branch before merging")
fi

# ── 4. Store the account ID as a GitHub secret ────────────────────────────
stage "Store your Cloudflare account ID"
say "CI needs your account ID to know which account to deploy to."
npx wrangler whoami 2>/dev/null | grep -iE "account (name|id)|│" || true
step "Copy the Account ID from the table above, or from the dashboard's account home page."
ask CLOUDFLARE_ACCOUNT_ID "Paste the account ID:"
set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"

# ── 5. Create a scoped API token for CI ───────────────────────────────────
stage "Create a scoped Cloudflare API token"
say "CI deploys with a token that can only edit Workers and D1 in this account."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Click 'Create Token', then 'Create Custom Token' (Get started)."
step "Name it: daily-checkin GitHub Actions"
step "Permissions: Account → Workers Scripts → Edit"
step "Add another: Account → D1 → Edit"
step "Account Resources: Include → your account. Leave the rest as is."
step "Continue to summary → Create Token, then copy the token (it is shown once)."
ask_secret CLOUDFLARE_API_TOKEN "Paste the token (input hidden):"
if [[ -z "$CLOUDFLARE_API_TOKEN" ]]; then
  printf '  %sNo token entered. Re-run the wizard.%s\n' "$RED" "$RESET"
  exit 1
fi

# ── 6. Store the token as a GitHub secret ─────────────────────────────────
stage "Store the API token as a GitHub secret"
say "The token goes straight to GitHub Secrets; it is never written to a file here."
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
unset CLOUDFLARE_API_TOKEN
note "GitHub should now hold exactly two secrets for this app:"
note "CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID."
pause

finish
say "Next:"
step "Commit the database_id in $WRANGLER_CONFIG to the pull request branch."
step "Merge the pull request; GitHub Actions deploys main."
step "Open https://daily-checkin.${WORKERS_SUBDOMAIN:-<subdomain>}.workers.dev/healthz"
printf '\n'
